/** Independent test math: ST-2084/HLG EOTF, FFmpeg Hable and display-referred
 * BT.709 (zimg uses inverse BT.1886). The no-mastering-metadata fixture reaches
 * tonemap already tagged linear, so FFmpeg's fallback peak is 10 (1000 nits).
 * No production adapter code or expected pixels generated by that adapter.
 */
export const HDR_LUMA_CODES = [64, 152, 283, 509, 723, 940] as const;
export const HDR_COLOR_CODES = [[400, 470, 555], [400, 560, 480], [500, 410, 520], [512, 512, 512], [360, 500, 540], [450, 550, 500]] as const;
export type HdrTransfer = "smpte2084" | "arib-std-b67";
export function hdrReference(code: number, transfer: HdrTransfer): number {
	const v = (code - 64) / 876, p = v ** (32 / 2523);
	const nits = transfer === "smpte2084"
		? 10000 * (Math.max(0, p - 3424 / 4096) / (2413 / 128 - 2392 / 128 * p)) ** (16384 / 2610)
		: 1000 * (v <= .5 ? v * v / 3 : (Math.exp((v - .55991073) / .17883277) + .28466892) / 12) ** 1.2;
	const hable = (x: number) => ((x * (.15 * x + .1 * .5) + .2 * .02) / (x * (.15 * x + .5) + .2 * .3)) - .02 / .3;
	const mapped = hable(nits / 100) / hable(10);
	return Math.min(255, Math.round(255 * mapped ** (1 / 2.4)));
}

// Remotion's transparent native PNG uses gamma 2.2 and BT.709 primaries.
// Browser Canvas readback is sRGB, so validate its color-managed pixels rather
// than equating the PNG's encoded samples with already displayed RGB samples.
export function nativePngDisplayReference(encoded: number): number {
	const linear = (encoded / 255) ** 2.2;
	return Math.round(255 * (linear <= .0031308 ? 12.92 * linear : 1.055 * linear ** (1 / 2.4) - .055));
}

/** Independent BT.2020 NCL YCbCr -> nonlinear RGB -> EOTF -> linear gamut
 * transform -> Hable -> display-referred BT.709. Used to catch a missing gamut
 * conversion that a neutral grayscale fixture cannot detect.
 */
export function hdrColorReference(codes: readonly number[], transfer: HdrTransfer, toneMapped: boolean): number[] {
	const y = (codes[0] - 64) / 876, cb = (codes[1] - 512) / 896, cr = (codes[2] - 512) / 896;
	const rgb = [y + 1.4746 * cr, y - .2627 * 1.4746 / .678 * cr - .0593 * 1.8814 / .678 * cb, y + 1.8814 * cb];
	const byte = (v: number) => Math.round(255 * Math.max(0, Math.min(1, v)));
	if (!toneMapped) return rgb.map(byte);
	const linear = rgb.map(v => {
		const p = Math.max(0, v) ** (32 / 2523);
		return transfer === "smpte2084"
			? 100 * (Math.max(0, p - 3424 / 4096) / (2413 / 128 - 2392 / 128 * p)) ** (16384 / 2610)
			: 10 * (v <= .5 ? v * v / 3 : (Math.exp((v - .55991073) / .17883277) + .28466892) / 12) ** 1.2;
	});
	const matrix = [[1.660491, -.587641, -.072850], [-.124550, 1.132900, -.008350], [-.018151, -.100579, 1.118730]];
	const gamut = matrix.map(row => row.reduce((sum, coefficient, i) => sum + coefficient * linear[i], 0));
	const hable = (x: number) => ((x * (.15 * x + .05) + .004) / (x * (.15 * x + .5) + .06)) - .02 / .3;
	const peak = Math.max(1e-6, ...gamut), scale = hable(peak) / hable(10) / peak;
	return gamut.map(v => byte(Math.max(0, v * scale) ** (1 / 2.4)));
}
